public class FirstPresentTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        java.util.Optional<String> a = java.util.Optional.of("alpha");
        java.util.Optional<String> b = java.util.Optional.of("beta");
        java.util.Optional<String> c = java.util.Optional.of("gamma");
        java.util.Optional<String> none = java.util.Optional.empty();
        check("all present -> first", java.util.Optional.of("alpha"), FirstPresent.firstPresent(a, b, c));
        check("first empty -> second", java.util.Optional.of("beta"), FirstPresent.firstPresent(none, b, c));
        check("first two empty -> third", java.util.Optional.of("gamma"), FirstPresent.firstPresent(none, none, c));
        check("all empty -> empty", java.util.Optional.empty(), FirstPresent.firstPresent(none, none, none));
        check("only first present", java.util.Optional.of("alpha"), FirstPresent.firstPresent(a, none, none));
        check("only second present", java.util.Optional.of("beta"), FirstPresent.firstPresent(none, b, none));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

