public class FirstPresent {

    public static java.util.Optional<String> firstPresent(java.util.Optional<String> a,
                                                          java.util.Optional<String> b,
                                                          java.util.Optional<String> c) {
        return a.or(() -> b).or(() -> c);
    }
}
